	win32.OSSelectClipRgn(this.Handle, rgn)
	var dwRop int32
	if win32.OSGetROP2(this.Handle) == win32.OSR2_XORPEN {
		dwRop = win32.OSSRCINVERT
	} else {
		dwRop = win32.OSSRCCOPY
	}
	if !simple && (srcWidth != destWidth || srcHeight != destHeight) {
		var mode int32 = win32.OSSetStretchBltMode(this.Handle, win32.OSCOLORONCOLOR)
		win32.OSStretchBlt(this.Handle, destX, destY, destWidth, destHeight, srcHdc, srcX, srcY, srcWidth, srcHeight, dwRop)
		win32.OSSetStretchBltMode(this.Handle, mode)
	} else {
		win32.OSBitBlt(this.Handle, destX, destY, destWidth, destHeight, srcHdc, srcX, srcY, dwRop)
	}
	var cond339 int64
	if result == 1 {
		cond339 = clip
	} else {
		cond339 = int64(0)
	}
	win32.OSSelectClipRgn(this.Handle, cond339)
